package main

import (
	"bytes"
	"errors"
	"fmt"
	"go/ast"
	"go/format"
	"go/parser"
	"go/printer"
	"go/token"
	"os"
	"os/exec"
	"path"
	"path/filepath"
	"sort"
	"strings"
	"sync"

	gofumpt "mvdan.cc/gofumpt/format"
)

type fileResult struct {
	Path    string
	AbsPath string
	Output  []byte
	Changed bool
	Error   error
}

type processor struct {
	cfg       config
	order     []string
	categories map[string]bool
	resolver  *resolver
}

func newProcessor(cfg config, order []string) (*processor, error) {
	return &processor{
		cfg:        cfg,
		order:      order,
		categories: makeCategorySet(order),
		resolver:   newResolver(),
	}, nil
}

func (p *processor) processInput(input string) ([]fileResult, error) {
	if p.cfg.output != "file" && p.cfg.output != "write" && p.cfg.output != "stdout" {
		return nil, fmt.Errorf("invalid output %q specified", p.cfg.output)
	}

	files, err := p.expandInput(input)
	if err != nil {
		return nil, err
	}

	results := make([]fileResult, 0, len(files))
	for _, file := range files {
		result := fileResult{Path: file}

		absPath, err := filepath.Abs(file)
		if err == nil {
			result.AbsPath = absPath
		} else {
			result.AbsPath = file
		}

		output, changed, err := p.processFile(file)
		result.Output = output
		result.Changed = changed
		result.Error = err
		results = append(results, result)
	}

	return results, nil
}

func (p *processor) expandInput(input string) ([]string, error) {
	if strings.HasSuffix(input, "/...") {
		root := strings.TrimSuffix(input, "/...")
		if root == "" {
			root = "."
		}
		return p.collectDir(root, true)
	}

	info, err := os.Stat(input)
	if err != nil {
		return []string{input}, nil
	}

	if info.IsDir() {
		return p.collectDir(input, p.cfg.recursive)
	}

	return []string{input}, nil
}

func (p *processor) collectDir(root string, recursive bool) ([]string, error) {
	files := []string{}
	walkFn := func(current string, entry os.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if current == root {
			return nil
		}

		rel, relErr := filepath.Rel(root, current)
		if relErr != nil {
			rel = current
		}
		rel = filepath.ToSlash(rel)

		if entry.IsDir() {
			if p.isExcluded(rel, true) {
				return filepath.SkipDir
			}
			if !recursive {
				return filepath.SkipDir
			}
			return nil
		}

		if filepath.Ext(current) != ".go" {
			return nil
		}
		if p.isExcluded(rel, false) {
			return nil
		}

		files = append(files, current)
		return nil
	}

	if recursive {
		if err := filepath.WalkDir(root, walkFn); err != nil {
			return nil, err
		}
	} else {
		entries, err := os.ReadDir(root)
		if err != nil {
			return nil, err
		}
		for _, entry := range entries {
			current := filepath.Join(root, entry.Name())
			if entry.IsDir() {
				if p.isExcluded(entry.Name(), true) {
					continue
				}
				continue
			}
			if filepath.Ext(current) != ".go" {
				continue
			}
			if p.isExcluded(entry.Name(), false) {
				continue
			}
			files = append(files, current)
		}
		sort.Strings(files)
	}

	return files, nil
}

func (p *processor) isExcluded(rel string, isDir bool) bool {
	rel = filepath.ToSlash(rel)
	relNoDot := strings.TrimPrefix(rel, "./")

	for _, pattern := range p.cfg.excludes {
		pattern = filepath.ToSlash(pattern)
		trimmedPattern := strings.TrimPrefix(pattern, "./")
		if strings.HasSuffix(trimmedPattern, "/") {
			dirPattern := strings.TrimSuffix(trimmedPattern, "/")
			if relNoDot == dirPattern || strings.HasPrefix(relNoDot, dirPattern+"/") {
				return true
			}
			continue
		}

		if ok, _ := path.Match(trimmedPattern, relNoDot); ok {
			return true
		}
		if isDir && okDirPattern(trimmedPattern, relNoDot); okDirPattern(trimmedPattern, relNoDot) {
			return true
		}
	}

	return false
}

func okDirPattern(pattern string, rel string) bool {
	if !strings.Contains(pattern, "*") {
		return false
	}
	match, _ := path.Match(pattern, rel+"/")
	return match
}

func (p *processor) processFile(filename string) ([]byte, bool, error) {
	original, err := os.ReadFile(filename)
	if err != nil {
		return nil, false, err
	}

	if isGeneratedFile(original) && !p.cfg.applyGenerated {
		return original, false, nil
	}

	dir := filepath.Dir(filename)
	fset := token.NewFileSet()
	file, err := parser.ParseFile(fset, filename, original, parser.ParseComments)
	if err != nil {
		return nil, false, err
	}

	if p.cfg.setAlias {
		if err := p.applySetAlias(dir, file); err != nil {
			return nil, false, err
		}
	}
	if p.cfg.rmUnused {
		p.removeUnusedImports(dir, file)
	}

	rewritten, err := p.rewriteSourceWithImports(fset, file, original)
	if err != nil {
		return nil, false, err
	}

	formatted, err := p.formatSource(dir, rewritten)
	if err != nil {
		return nil, false, err
	}

	changed := !bytes.Equal(original, formatted)
	return formatted, changed, nil
}

func (p *processor) applySetAlias(dir string, file *ast.File) error {
	var errs []error
	for _, spec := range file.Imports {
		if spec.Name != nil {
			continue
		}

		importPath := strings.Trim(spec.Path.Value, `"`)
		pkgName, stderr, err := p.resolver.packageName(dir, importPath)
		if err != nil {
			if stderr != "" {
				lines := strings.Split(strings.TrimSuffix(stderr, "\n"), "\n")
				for _, line := range lines {
					if line != "" {
						fmt.Fprintln(os.Stderr, line)
					}
				}
			}
			errs = append(errs, err)
			continue
		}

		if pkgName != path.Base(importPath) {
			spec.Name = ast.NewIdent(pkgName)
		}
	}

	if len(errs) > 0 {
		return errors.New("package has an errors")
	}
	return nil
}

func (p *processor) removeUnusedImports(dir string, file *ast.File) {
	for _, spec := range file.Imports {
		if spec.Name != nil {
			if spec.Name.Name == "_" || spec.Name.Name == "." {
				return
			}
		}
	}

	used := map[string]bool{}
	ast.Inspect(file, func(n ast.Node) bool {
		sel, ok := n.(*ast.SelectorExpr)
		if !ok {
			return true
		}
		ident, ok := sel.X.(*ast.Ident)
		if ok {
			used[ident.Name] = true
		}
		return true
	})

	for _, decl := range file.Decls {
		gen, ok := decl.(*ast.GenDecl)
		if !ok || gen.Tok != token.IMPORT {
			continue
		}

		filtered := make([]ast.Spec, 0, len(gen.Specs))
		for _, spec := range gen.Specs {
			importSpec := spec.(*ast.ImportSpec)
			if shouldKeepImport(dir, importSpec, used, p.resolver) {
				filtered = append(filtered, spec)
			}
		}
		gen.Specs = filtered
	}

	filteredImports := make([]*ast.ImportSpec, 0, len(file.Imports))
	for _, spec := range file.Imports {
		for _, decl := range file.Decls {
			gen, ok := decl.(*ast.GenDecl)
			if !ok || gen.Tok != token.IMPORT {
				continue
			}
			for _, kept := range gen.Specs {
				if kept == spec {
					filteredImports = append(filteredImports, spec)
					goto nextImport
				}
			}
		}
	nextImport:
	}
	file.Imports = filteredImports
}

func shouldKeepImport(dir string, spec *ast.ImportSpec, used map[string]bool, resolver *resolver) bool {
	if spec.Name != nil {
		return used[spec.Name.Name]
	}

	importPath := strings.Trim(spec.Path.Value, `"`)
	pkgName, _, err := resolver.packageName(dir, importPath)
	if err != nil {
		return true
	}
	return used[pkgName]
}

func (p *processor) rewriteSourceWithImports(fset *token.FileSet, file *ast.File, src []byte) ([]byte, error) {
	type replacement struct {
		start int
		end   int
		text  []byte
	}

	replacements := []replacement{}
	newDecls := make([]ast.Decl, 0, len(file.Decls))
	for _, decl := range file.Decls {
		gen, ok := decl.(*ast.GenDecl)
		if !ok || gen.Tok != token.IMPORT {
			newDecls = append(newDecls, decl)
			continue
		}

		start := fset.Position(gen.Pos()).Offset
		end := fset.Position(gen.End()).Offset

		text, keep, err := p.renderImportDecl(fset, file, gen)
		if err != nil {
			return nil, err
		}
		replacements = append(replacements, replacement{
			start: start,
			end:   end,
			text:  text,
		})
		if keep {
			newDecls = append(newDecls, decl)
		}
	}
	file.Decls = newDecls

	if len(replacements) == 0 {
		return src, nil
	}

	sort.Slice(replacements, func(i, j int) bool {
		return replacements[i].start < replacements[j].start
	})

	var buf bytes.Buffer
	prev := 0
	for _, repl := range replacements {
		buf.Write(src[prev:repl.start])
		buf.Write(repl.text)
		prev = repl.end
	}
	buf.Write(src[prev:])
	return buf.Bytes(), nil
}

func (p *processor) renderImportDecl(fset *token.FileSet, file *ast.File, decl *ast.GenDecl) ([]byte, bool, error) {
	if len(decl.Specs) == 0 {
		return nil, false, nil
	}

	groups := map[string][]*ast.ImportSpec{}
	for _, spec := range decl.Specs {
		importSpec := spec.(*ast.ImportSpec)
		groupName := p.groupForImport(file, importSpec)
		groups[groupName] = append(groups[groupName], importSpec)
	}

	for key := range groups {
		sort.Slice(groups[key], func(i, j int) bool {
			left := strings.Trim(groups[key][i].Path.Value, `"`)
			right := strings.Trim(groups[key][j].Path.Value, `"`)
			return left < right
		})
	}

	blocks := [][]*ast.ImportSpec{}
	for _, name := range p.order {
		specs := groups[name]
		if len(specs) == 0 {
			continue
		}

		if p.cfg.separateNamed && name != "blanked" && name != "dotted" {
			plain := make([]*ast.ImportSpec, 0, len(specs))
			named := make([]*ast.ImportSpec, 0, len(specs))
			for _, spec := range specs {
				if spec.Name == nil {
					plain = append(plain, spec)
				} else {
					named = append(named, spec)
				}
			}
			if len(plain) > 0 {
				blocks = append(blocks, plain)
			}
			if len(named) > 0 {
				blocks = append(blocks, named)
			}
			continue
		}

		blocks = append(blocks, specs)
	}

	if len(blocks) == 0 {
		return nil, false, nil
	}

	var buf bytes.Buffer
	buf.WriteString("import (\n")
	for i, block := range blocks {
		if i > 0 {
			buf.WriteString("\n")
		}
		for _, spec := range block {
			var specBuf bytes.Buffer
			if err := printer.Fprint(&specBuf, fset, spec); err != nil {
				return nil, false, err
			}

			text := strings.TrimSuffix(specBuf.String(), "\n")
			lines := strings.Split(text, "\n")
			for idx, line := range lines {
				buf.WriteString("\t")
				buf.WriteString(line)
				buf.WriteByte('\n')
				if idx == len(lines)-1 {
					continue
				}
			}
		}
	}
	buf.WriteString(")\n")

	return buf.Bytes(), true, nil
}

func (p *processor) groupForImport(file *ast.File, spec *ast.ImportSpec) string {
	importPath := strings.Trim(spec.Path.Value, `"`)

	if spec.Name != nil && p.categories["blanked"] && spec.Name.Name == "_" {
		return "blanked"
	}
	if spec.Name != nil && p.categories["dotted"] && spec.Name.Name == "." {
		return "dotted"
	}

	if p.resolver.isStdlib(importPath) {
		return "std"
	}

	projectName := p.cfg.projectName
	if projectName == "" {
		projectName = p.resolver.modulePath(file.Name.Name)
	}
	if projectName != "" && (importPath == projectName || strings.HasPrefix(importPath, projectName+"/")) {
		return "project"
	}

	for _, prefix := range p.cfg.companyPrefixes {
		if importPath == prefix || strings.HasPrefix(importPath, prefix+"/") {
			return "company"
		}
	}

	return "general"
}

func (p *processor) formatSource(dir string, src []byte) ([]byte, error) {
	if p.cfg.format {
		modulePath := p.cfg.projectName
		if modulePath == "" {
			modulePath = p.resolver.modulePath(dir)
		}
		return gofumpt.Source(src, gofumpt.Options{
			LangVersion: "1.21",
			ModulePath:  modulePath,
		})
	}
	return format.Source(src)
}

func isGeneratedFile(src []byte) bool {
	lines := strings.Split(string(src), "\n")
	for _, line := range lines {
		trimmed := strings.TrimSpace(line)
		if trimmed == "" {
			continue
		}
		return strings.HasPrefix(trimmed, "// Code generated")
	}
	return false
}

func parseImportsOrder(value string) ([]string, error) {
	parts := splitCSV(value)
	if len(parts) < 4 {
		return nil, errors.New(`use default at least 4 parameters to sort groups of your imports: "std,general,company,project"`)
	}

	allowed := map[string]bool{
		"std":      true,
		"general":  true,
		"company":  true,
		"project":  true,
		"blanked":  true,
		"dotted":   true,
	}
	required := map[string]bool{
		"std":     false,
		"general": false,
		"company": false,
		"project": false,
	}
	for _, part := range parts {
		if !allowed[part] {
			return nil, fmt.Errorf("unknown order group type: %q", part)
		}
		if _, ok := required[part]; ok {
			required[part] = true
		}
	}
	for _, ok := range required {
		if !ok {
			return nil, errors.New(`use default at least 4 parameters to sort groups of your imports: "std,general,company,project"`)
		}
	}
	return parts, nil
}

func makeCategorySet(order []string) map[string]bool {
	result := make(map[string]bool, len(order))
	for _, value := range order {
		result[value] = true
	}
	return result
}

type resolver struct {
	mu          sync.Mutex
	nameCache   map[string]resolverResult
	moduleCache map[string]string
	stdOnce     sync.Once
	stdSet      map[string]bool
}

type resolverResult struct {
	name   string
	stderr string
	err    error
}

func newResolver() *resolver {
	return &resolver{
		nameCache:   map[string]resolverResult{},
		moduleCache: map[string]string{},
	}
}

func (r *resolver) packageName(dir string, importPath string) (string, string, error) {
	key := dir + "\x00" + importPath

	r.mu.Lock()
	if cached, ok := r.nameCache[key]; ok {
		r.mu.Unlock()
		return cached.name, cached.stderr, cached.err
	}
	r.mu.Unlock()

	cmd := exec.Command("go", "list", "-find", "-f", "{{.Name}}", importPath)
	cmd.Dir = dir
	var stdout bytes.Buffer
	var stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	err := cmd.Run()

	result := resolverResult{
		name:   strings.TrimSpace(stdout.String()),
		stderr: stderr.String(),
		err:    err,
	}

	r.mu.Lock()
	r.nameCache[key] = result
	r.mu.Unlock()
	return result.name, result.stderr, result.err
}

func (r *resolver) modulePath(dir string) string {
	r.mu.Lock()
	if value, ok := r.moduleCache[dir]; ok {
		r.mu.Unlock()
		return value
	}
	r.mu.Unlock()

	origDir := dir
	for {
		goModPath := filepath.Join(dir, "go.mod")
		content, err := os.ReadFile(goModPath)
		if err == nil {
			module := parseModuleDirective(content)
			r.mu.Lock()
			r.moduleCache[origDir] = module
			r.mu.Unlock()
			return module
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			r.mu.Lock()
			r.moduleCache[origDir] = ""
			r.mu.Unlock()
			return ""
		}
		dir = parent
	}
}

func parseModuleDirective(content []byte) string {
	lines := strings.Split(string(content), "\n")
	for _, line := range lines {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "//") {
			continue
		}
		if strings.HasPrefix(line, "module ") {
			fields := strings.Fields(line)
			if len(fields) >= 2 {
				return strings.Trim(fields[1], `"`)
			}
		}
	}
	return ""
}

func (r *resolver) isStdlib(importPath string) bool {
	r.stdOnce.Do(func() {
		r.stdSet = map[string]bool{}
		cmd := exec.Command("go", "list", "std")
		var stdout bytes.Buffer
		cmd.Stdout = &stdout
		if err := cmd.Run(); err == nil {
			for _, line := range strings.Split(stdout.String(), "\n") {
				line = strings.TrimSpace(line)
				if line != "" {
					r.stdSet[line] = true
				}
			}
		}
	})

	if r.stdSet[importPath] {
		return true
	}
	first := strings.Split(importPath, "/")[0]
	return first != "" && !strings.Contains(first, ".")
}

