	setAlias       bool
	setExitStatus  bool
	useCache       bool
	version        bool
	versionOnly    bool
}

func main() {
	log.SetFlags(log.LstdFlags)

	cfg := config{}
	flag.BoolVar(&cfg.applyGenerated, "apply-to-generated-files", false, "Apply imports sorting and formatting(if the option is set) to generated files. Generated file is a file with first comment which starts with comment '// Code generated'. Optional parameter.")
	flag.StringVar(&cfg.companyPrefixes, "company-prefixes", "", "Company package prefixes which will be placed after 3rd-party group by default(if defined). Values should be comma-separated. Optional parameters.")
	flag.StringVar(&cfg.excludes, "excludes", "", "Exclude files or dirs, example: '.git/,proto/*.go'.")
	flag.StringVar(&cfg.filePath, "file-path", "", "Deprecated. Put file name as an argument(last item) of command line.")
	flag.BoolVar(&cfg.format, "format", false, "Option will perform additional formatting. Optional parameter.")
	flag.StringVar(&cfg.importsOrder, "imports-order", "std,general,company,project", "Your imports groups can be sorted in your way. \nstd - std import group; \ngeneral - libs for general purpose; \ncompany - inter-org or your company libs(if you set '-company-prefixes'-option, then 4th group will be split separately. In other case, it will be the part of general purpose libs); \nproject - your local project dependencies;\nblanked - imports with \"_\" alias;\ndotted - imports with \".\" alias.\nOptional parameter.")
	flag.BoolVar(&cfg.listDiff, "list-diff", false, "Option will list files whose formatting differs from goimports-reviser. Optional parameter.")
	flag.StringVar(&cfg.local, "local", "", "Deprecated")
	flag.StringVar(&cfg.output, "output", "file", "Can be \"file\", \"write\" or \"stdout\". Whether to write the formatted content back to the file or to stdout. When \"write\" together with \"-list-diff\" will list the file name and write back to the file. Optional parameter.")
	flag.StringVar(&cfg.projectName, "project-name", "", "Your project name(ex.: github.com/incu6us/goimports-reviser). Optional parameter.")
	flag.BoolVar(&cfg.recursive, "recursive", false, "Apply rules recursively if target is a directory. In case of ./... execution will be recursively applied by default. Optional parameter.")
	flag.BoolVar(&cfg.rmUnused, "rm-unused", false, "Remove unused imports. Optional parameter.")
	flag.BoolVar(&cfg.separateNamed, "separate-named", false, "Option will separate named imports from the rest of the imports, per group. Optional parameter.")
	flag.BoolVar(&cfg.setAlias, "set-alias", false, "Set alias for versioned package names, like 'github.com/go-pg/pg/v9'. In this case import will be set as 'pg \"github.com/go-pg/pg/v9\"'. Optional parameter.")
	flag.BoolVar(&cfg.setExitStatus, "set-exit-status", false, "set the exit status to 1 if a change is needed/made. Optional parameter.")
	flag.BoolVar(&cfg.useCache, "use-cache", false, "Use cache to improve performance. Optional parameter.")
	flag.BoolVar(&cfg.version, "version", false, "Show version information")
	flag.BoolVar(&cfg.versionOnly, "version-only", false, "Show only the version string")
	flag.Parse()

	if cfg.versionOnly {
		fmt.Println(versionString)
		return
	}
	if cfg.version {
		fmt.Printf("version: %s\n", versionString)
		fmt.Printf("built with: %s\n", builtWith)
		fmt.Printf("tag: %s\n", tagString)
		fmt.Printf("commit: %s\n", commitString)
		fmt.Printf("source: %s\n", sourceString)
		return
	}

	order, err := parseImportsOrder(cfg.importsOrder)
	if err != nil {
		flag.Usage()
		log.Println(err.Error())
		os.Exit(1)
	}

	paths := flag.Args()
	if cfg.filePath != "" {
		paths = append(paths, cfg.filePath)
	}
	if len(paths) == 0 {
		flag.Usage()
		log.Println("no file(s) or directory(ies) specified on input")
		os.Exit(1)
	}

	cfg.companyPrefixes = splitCSV(cfg.companyPrefixes)
	if cfg.local != "" {
		cfg.companyPrefixes = append(cfg.companyPrefixes, splitCSV(cfg.local)...)
	}
	cfg.excludes = splitCSV(cfg.excludes)

	processor, err := newProcessor(cfg, order)
	if err != nil {
		log.Println(err.Error())
		os.Exit(1)
	}

	log.Printf("Paths: %v", paths)

	exitCode := 0
	hadError := false
	hadChange := false

	for _, input := range paths {
		log.Printf("Processing %s", input)

		fileResults, err := processor.processInput(input)
		if err != nil {
			log.Printf("Failed to fix file: %v", err)
			hadError = true
			continue
		}

		for _, result := range fileResults {
			if result.Error != nil {
				log.Printf("Failed to fix file: %v", result.Error)
				hadError = true
				continue
			}

			if cfg.listDiff {
				fmt.Println(result.AbsPath)
			} else if cfg.output == "stdout" {
				fmt.Print(string(result.Output))
			}

			if (cfg.output == "file" || cfg.output == "write") && result.Changed {
				if err := os.WriteFile(result.Path, result.Output, 0o644); err != nil {
					log.Printf("Failed to fix file: %v", err)
					hadError = true
					continue
				}
			}

			if result.Changed {
				hadChange = true
			}
		}
	}

	if cfg.filePath != "" {
		log.Println("-file-path is deprecated. Put file name(s) as last argument to the command(Example: goimports-reviser -rm-unused -set-alias -format goimports-reviser/main.go)")
		log.Println("All changes to file are applied, but command-line syntax should be fixed")
		exitCode = 1
	}
	if cfg.local != "" {
		log.Println("-local is deprecated and will be removed soon. Use -company-prefixes instead.")
		log.Println("All changes to file are applied, but command-line syntax should be fixed")
		exitCode = 1
	}
	if hadError {
		exitCode = 1
	}
	if cfg.setExitStatus && hadChange {
		exitCode = 1
	}

	os.Exit(exitCode)
}

func splitCSV(value string) []string {
	if value == "" {
		return nil
	}
	parts := strings.Split(value, ",")
	result := make([]string, 0, len(parts))
	for _, part := range parts {
		part = strings.TrimSpace(part)
		if part != "" {
			result = append(result, part)
		}
	}
	return result
}

