func (p *processor) rewriteSourceWithImports(fset *token.FileSet, file *ast.File, src []byte) ([]byte, error) {
	type replacement struct {
		start int
		end   int
		text  []byte
	}

	replacements := []replacement{}
	newDecls := make([]ast.Decl, 0, len(file.Decls))
	for _, decl := range file.Decls {
		gen, ok := decl.(*ast.GenDecl)
		if !ok || gen.Tok != token.IMPORT {
			newDecls = append(newDecls, decl)
			continue
		}

		start := fset.Position(gen.Pos()).Offset
		end := fset.Position(gen.End()).Offset

		text, keep, err := p.renderImportDecl(fset, file, gen)
		if err != nil {
			return nil, err
		}
		replacements = append(replacements, replacement{
			start: start,
			end:   end,
			text:  text,
		})
		if keep {
			newDecls = append(newDecls, decl)
		}
	}
	file.Decls = newDecls

	if len(replacements) == 0 {
		return src, nil
	}

	sort.Slice(replacements, func(i, j int) bool {
		return replacements[i].start < replacements[j].start
	})

	var buf bytes.Buffer
	prev := 0
	for _, repl := range replacements {
		buf.Write(src[prev:repl.start])
		buf.Write(repl.text)
		prev = repl.end
	}
	buf.Write(src[prev:])
	return buf.Bytes(), nil
}

func (p *processor) renderImportDecl(fset *token.FileSet, file *ast.File, decl *ast.GenDecl) ([]byte, bool, error) {
	if len(decl.Specs) == 0 {
		return nil, false, nil
	}

	groups := map[string][]*ast.ImportSpec{}
	for _, spec := range decl.Specs {
		importSpec := spec.(*ast.ImportSpec)
		groupName := p.groupForImport(file, importSpec)
		groups[groupName] = append(groups[groupName], importSpec)
	}

	for key := range groups {
		sort.Slice(groups[key], func(i, j int) bool {
			left := strings.Trim(groups[key][i].Path.Value, `"`)
			right := strings.Trim(groups[key][j].Path.Value, `"`)
			return left < right
		})
	}

	blocks := [][]*ast.ImportSpec{}
	for _, name := range p.order {
		specs := groups[name]
		if len(specs) == 0 {
			continue
		}

		if p.cfg.separateNamed && name != "blanked" && name != "dotted" {
			plain := make([]*ast.ImportSpec, 0, len(specs))
			named := make([]*ast.ImportSpec, 0, len(specs))
			for _, spec := range specs {
				if spec.Name == nil {
					plain = append(plain, spec)
				} else {
					named = append(named, spec)
				}
			}
			if len(plain) > 0 {
				blocks = append(blocks, plain)
			}
			if len(named) > 0 {
				blocks = append(blocks, named)
			}
			continue
		}

		blocks = append(blocks, specs)
	}

	if len(blocks) == 0 {
		return nil, false, nil
	}

	var buf bytes.Buffer
	buf.WriteString("import (\n")
	for i, block := range blocks {
		if i > 0 {
			buf.WriteString("\n")
		}
		for _, spec := range block {
			var specBuf bytes.Buffer
			if err := printer.Fprint(&specBuf, fset, spec); err != nil {
				return nil, false, err
			}

			text := strings.TrimSuffix(specBuf.String(), "\n")
			lines := strings.Split(text, "\n")
			for idx, line := range lines {
				buf.WriteString("\t")
				buf.WriteString(line)
				buf.WriteByte('\n')
				if idx == len(lines)-1 {
					continue
				}
			}
		}
	}
	buf.WriteString(")\n")

	return buf.Bytes(), true, nil
}

func (p *processor) groupForImport(file *ast.File, spec *ast.ImportSpec) string {
	importPath := strings.Trim(spec.Path.Value, `"`)

	if spec.Name != nil && p.categories["blanked"] && spec.Name.Name == "_" {
		return "blanked"
	}
	if spec.Name != nil && p.categories["dotted"] && spec.Name.Name == "." {
		return "dotted"
	}

	if p.resolver.isStdlib(importPath) {
		return "std"
	}

	projectName := p.cfg.projectName
	if projectName == "" {
		projectName = p.resolver.modulePath(file.Name.Name)
	}
	if projectName != "" && (importPath == projectName || strings.HasPrefix(importPath, projectName+"/")) {
		return "project"
	}

	for _, prefix := range p.cfg.companyPrefixes {
		if importPath == prefix || strings.HasPrefix(importPath, prefix+"/") {
			return "company"
		}
	}

	return "general"
}

