type resolver struct {
	mu          sync.Mutex
	nameCache   map[string]resolverResult
	moduleCache map[string]string
	stdOnce     sync.Once
	stdSet      map[string]bool
}

type resolverResult struct {
	name   string
	stderr string
	err    error
}

func newResolver() *resolver {
	return &resolver{
		nameCache:   map[string]resolverResult{},
		moduleCache: map[string]string{},
	}
}

func (r *resolver) packageName(dir string, importPath string) (string, string, error) {
	key := dir + "\x00" + importPath

	r.mu.Lock()
	if cached, ok := r.nameCache[key]; ok {
		r.mu.Unlock()
		return cached.name, cached.stderr, cached.err
	}
	r.mu.Unlock()

	cmd := exec.Command("go", "list", "-find", "-f", "{{.Name}}", importPath)
	cmd.Dir = dir
	var stdout bytes.Buffer
	var stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	err := cmd.Run()

	result := resolverResult{
		name:   strings.TrimSpace(stdout.String()),
		stderr: stderr.String(),
		err:    err,
	}

	r.mu.Lock()
	r.nameCache[key] = result
	r.mu.Unlock()
	return result.name, result.stderr, result.err
}

func (r *resolver) modulePath(dir string) string {
	r.mu.Lock()
	if value, ok := r.moduleCache[dir]; ok {
		r.mu.Unlock()
		return value
	}
	r.mu.Unlock()

	origDir := dir
	for {
		goModPath := filepath.Join(dir, "go.mod")
		content, err := os.ReadFile(goModPath)
		if err == nil {
			module := parseModuleDirective(content)
			r.mu.Lock()
			r.moduleCache[origDir] = module
			r.mu.Unlock()
			return module
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			r.mu.Lock()
			r.moduleCache[origDir] = ""
			r.mu.Unlock()
			return ""
		}
		dir = parent
	}
}

func parseModuleDirective(content []byte) string {
	lines := strings.Split(string(content), "\n")
	for _, line := range lines {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "//") {
			continue
		}
		if strings.HasPrefix(line, "module ") {
			fields := strings.Fields(line)
			if len(fields) >= 2 {
				return strings.Trim(fields[1], `"`)
			}
		}
	}
	return ""
}

func (r *resolver) isStdlib(importPath string) bool {
	r.stdOnce.Do(func() {
		r.stdSet = map[string]bool{}
		cmd := exec.Command("go", "list", "std")
		var stdout bytes.Buffer
		cmd.Stdout = &stdout
		if err := cmd.Run(); err == nil {
			for _, line := range strings.Split(stdout.String(), "\n") {
				line = strings.TrimSpace(line)
				if line != "" {
					r.stdSet[line] = true
				}
			}
		}
	})

	if r.stdSet[importPath] {
		return true
	}
	first := strings.Split(importPath, "/")[0]
	return first != "" && !strings.Contains(first, ".")
}

