func parseImportsOrder(value string) ([]groupType, error) {
	parts := splitCSV(value)
	if len(parts) < 4 {
		return nil, fmtUsageErrorf("use default at least 4 parameters to sort groups of your imports: %q", value)
	}

	order := make([]groupType, 0, len(parts))
	for _, part := range parts {
		group, ok := knownGroups[part]
		if !ok {
			return nil, fmtUsageErrorf("unknown order group type: %q", part)
		}
		order = append(order, group)
	}
	return order, nil
}

func sortImports(entries []importEntry, cfg config, projectName string) ([]importEntry, [][]importEntry) {
	grouped := map[groupType][]importEntry{
		groupStd:     nil,
		groupGeneral: nil,
		groupCompany: nil,
		groupProject: nil,
		groupBlanked: nil,
		groupDotted:  nil,
	}

	useBlanked := hasGroup(cfg.importsOrder, groupBlanked)
	useDotted := hasGroup(cfg.importsOrder, groupDotted)

	for _, entry := range entries {
		entry.renderGroup = classifyImport(entry, cfg.company, projectName, useBlanked, useDotted)
		grouped[entry.renderGroup] = append(grouped[entry.renderGroup], entry)
	}

	for group, groupEntries := range grouped {
		sort.SliceStable(groupEntries, func(i, j int) bool {
			return groupEntries[i].path < groupEntries[j].path
		})
		grouped[group] = groupEntries
	}

	ordered := make([]importEntry, 0, len(entries))
	segments := make([][]importEntry, 0, len(cfg.importsOrder))

	for _, group := range cfg.importsOrder {
		groupEntries := grouped[group]
		if len(groupEntries) == 0 {
			continue
		}
		if cfg.separateNamed {
			var unnamed []importEntry
			var named []importEntry
			for _, entry := range groupEntries {
				if entry.name == "" {
					unnamed = append(unnamed, entry)
				} else {
					named = append(named, entry)
				}
			}
			if len(unnamed) > 0 {
				segments = append(segments, unnamed)
				ordered = append(ordered, unnamed...)
			}
			if len(named) > 0 {
				segments = append(segments, named)
				ordered = append(ordered, named...)
			}
			continue
		}
		segments = append(segments, groupEntries)
		ordered = append(ordered, groupEntries...)
	}

	return ordered, segments
}

func classifyImport(entry importEntry, company []string, projectName string, useBlanked, useDotted bool) groupType {
	if entry.name == "_" && useBlanked {
		return groupBlanked
	}
	if entry.name == "." && useDotted {
		return groupDotted
	}
	if isProjectImport(entry.path, projectName) {
		return groupProject
	}
	if isCompanyImport(entry.path, company) {
		return groupCompany
	}
	if isStdImport(entry.path) {
		return groupStd
	}
	return groupGeneral
}

func hasGroup(order []groupType, want groupType) bool {
	for _, group := range order {
		if group == want {
			return true
		}
	}
	return false
}

func isStdImport(importPath string) bool {
	first := importPath
	if idx := strings.Index(importPath, "/"); idx >= 0 {
		first = importPath[:idx]
	}
	return !strings.Contains(first, ".")
}

func isProjectImport(importPath, projectName string) bool {
	return projectName != "" && (importPath == projectName || strings.HasPrefix(importPath, projectName+"/"))
}

func isCompanyImport(importPath string, prefixes []string) bool {
	for _, prefix := range prefixes {
		if importPath == prefix || strings.HasPrefix(importPath, prefix+"/") {
			return true
		}
	}
	return false
}

func needsAlias(importPath string) bool {
	last := path.Base(importPath)
	return versionSegmentPattern.MatchString(last) || gopkgVersionPattern.MatchString(last)
}

func fallbackPackageName(importPath string) string {
	last := path.Base(importPath)
	if match := gopkgVersionPattern.FindStringSubmatch(last); len(match) == 2 {
		return match[1]
	}
	if versionSegmentPattern.MatchString(last) {
		parent := path.Base(path.Dir(importPath))
		if parent != "." && parent != "/" {
			return parent
		}
	}
	return last
}

