func filterComments(file *ast.File, inline map[*ast.CommentGroup]struct{}, cDecls []*ast.GenDecl, entries []importEntry) []*ast.CommentGroup {
	keep := map[*ast.CommentGroup]struct{}{}
	for group := range inline {
		keep[group] = struct{}{}
	}
	for _, entry := range entries {
		if entry.original.Comment != nil {
			keep[entry.original.Comment] = struct{}{}
		}
	}

	var importRanges [][2]token.Pos
	for _, decl := range file.Decls {
		gen, ok := decl.(*ast.GenDecl)
		if !ok || gen.Tok != token.IMPORT {
			continue
		}

		hasNonC := false
		for _, spec := range gen.Specs {
			if strings.Trim(spec.(*ast.ImportSpec).Path.Value, `"`) != "C" {
				hasNonC = true
				break
			}
		}
		if hasNonC {
			importRanges = append(importRanges, [2]token.Pos{gen.Pos(), gen.End()})
		}
	}

	for _, decl := range cDecls {
		if decl.Doc != nil {
			keep[decl.Doc] = struct{}{}
		}
		for _, spec := range decl.Specs {
			importSpec := spec.(*ast.ImportSpec)
			if importSpec.Doc != nil {
				keep[importSpec.Doc] = struct{}{}
			}
			if importSpec.Comment != nil {
				keep[importSpec.Comment] = struct{}{}
			}
		}
	}

	comments := make([]*ast.CommentGroup, 0, len(file.Comments))
	for _, group := range file.Comments {
		if _, ok := keep[group]; ok {
			comments = append(comments, group)
			continue
		}
		if !inAnyRange(group.Pos(), importRanges) {
			comments = append(comments, group)
		}
	}

	sort.Slice(comments, func(i, j int) bool {
		return comments[i].Pos() < comments[j].Pos()
	})
	return comments
}

func inAnyRange(pos token.Pos, ranges [][2]token.Pos) bool {
	for _, pair := range ranges {
		if pos >= pair[0] && pos < pair[1] {
			return true
		}
	}
	return false
}

func rebuildDecls(file *ast.File, cDecls []*ast.GenDecl, entries []importEntry) {
	var rebuilt []ast.Decl
	inserted := false

	for _, decl := range file.Decls {
		gen, ok := decl.(*ast.GenDecl)
		if ok && gen.Tok == token.IMPORT {
			if !inserted {
				for _, cDecl := range cDecls {
					rebuilt = append(rebuilt, cDecl)
				}
				if len(entries) > 0 {
					rebuilt = append(rebuilt, buildImportDecl(entries))
				}
				inserted = true
			}
			continue
		}
		rebuilt = append(rebuilt, decl)
	}

	if !inserted && (len(cDecls) > 0 || len(entries) > 0) {
		var withImports []ast.Decl
		for _, cDecl := range cDecls {
			withImports = append(withImports, cDecl)
		}
		if len(entries) > 0 {
			withImports = append(withImports, buildImportDecl(entries))
		}
		withImports = append(withImports, rebuilt...)
		rebuilt = withImports
	}

	file.Decls = rebuilt
}

func updateFileImports(file *ast.File, cDecls []*ast.GenDecl, entries []importEntry) {
	imports := make([]*ast.ImportSpec, 0, len(cDecls)+len(entries))
	for _, decl := range cDecls {
		for _, spec := range decl.Specs {
			imports = append(imports, spec.(*ast.ImportSpec))
		}
	}
	for _, entry := range entries {
		imports = append(imports, buildImportSpec(entry))
	}
	file.Imports = imports
}

func buildImportDecl(entries []importEntry) *ast.GenDecl {
	specs := make([]ast.Spec, 0, len(entries))
	for _, entry := range entries {
		specs = append(specs, buildImportSpec(entry))
	}

	decl := &ast.GenDecl{
		Tok:   token.IMPORT,
		Specs: specs,
	}
	if len(entries) > 1 {
		decl.Lparen = token.Pos(1)
		decl.Rparen = token.Pos(1)
	}
	return decl
}

func buildImportSpec(entry importEntry) *ast.ImportSpec {
	spec := &ast.ImportSpec{
		Path: &ast.BasicLit{Kind: token.STRING, Value: entry.pathValue},
	}
	if entry.name != "" {
		spec.Name = ast.NewIdent(entry.name)
	}
	if entry.original.Comment != nil {
		spec.Comment = entry.original.Comment
	}
	return spec
}

func printFile(fset *token.FileSet, file *ast.File) ([]byte, error) {
	var buf bytes.Buffer
	cfg := printer.Config{Mode: printer.UseSpaces | printer.TabIndent, Tabwidth: 8}
	if err := cfg.Fprint(&buf, fset, file); err != nil {
		return nil, err
	}
	return buf.Bytes(), nil
}

func needsGroupedImportRewrite(segments [][]importEntry) bool {
	return len(segments) > 1
}

func buildGroupedImportBlock(segments [][]importEntry) string {
	var b strings.Builder
	b.WriteString("import (\n")
	for i, segment := range segments {
		if i > 0 {
			b.WriteString("\n")
		}
		for _, entry := range segment {
			b.WriteString("\t")
			if entry.name != "" {
				b.WriteString(entry.name)
				b.WriteString(" ")
			}
			b.WriteString(entry.pathValue)
			if entry.inline != "" {
				b.WriteString("\t")
				b.WriteString(entry.inline)
			}
			b.WriteString("\n")
		}
	}
	b.WriteString(")")
	return b.String()
}

func replaceNonCImportDecl(src []byte, replacement string) ([]byte, error) {
	fset := token.NewFileSet()
	file, err := parser.ParseFile(fset, "", src, parser.ParseComments)
	if err != nil {
		return nil, err
	}

	for _, decl := range file.Decls {
		gen, ok := decl.(*ast.GenDecl)
		if !ok || gen.Tok != token.IMPORT {
			continue
		}
		hasNonC := false
		for _, spec := range gen.Specs {
			if strings.Trim(spec.(*ast.ImportSpec).Path.Value, `"`) != "C" {
				hasNonC = true
				break
			}
		}
		if !hasNonC {
			continue
		}

		start := fset.Position(gen.Pos()).Offset
		end := fset.Position(gen.End()).Offset
		out := make([]byte, 0, len(src)-((end-start)-len(replacement)))
		out = append(out, src[:start]...)
		out = append(out, replacement...)
		out = append(out, src[end:]...)
		return out, nil
	}

	return src, nil
}

func cloneImportDecl(gen *ast.GenDecl) *ast.GenDecl {
	clone := &ast.GenDecl{
		Doc:    gen.Doc,
		TokPos: gen.TokPos,
		Tok:    gen.Tok,
		Lparen: gen.Lparen,
		Rparen: gen.Rparen,
	}
	for _, spec := range gen.Specs {
		clone.Specs = append(clone.Specs, spec)
	}
	return clone
}

func singleImportDecl(spec *ast.ImportSpec, doc *ast.CommentGroup) *ast.GenDecl {
	return &ast.GenDecl{
		Doc:   doc,
		Tok:   token.IMPORT,
		Specs: []ast.Spec{spec},
	}
}

func joinCommentGroup(group *ast.CommentGroup) string {
	parts := make([]string, 0, len(group.List))
	for _, comment := range group.List {
		parts = append(parts, comment.Text)
	}
	return strings.Join(parts, " ")
}

